  /* ===================== mapping tables ===================== */
  var ACC_TYPE = { BANK: 'bank', AR: 'ar', OCASSET: 'oca', FIXASSET: 'fixed', OASSET: 'oa', AP: 'ap', CCARD: 'cc', OCLIAB: 'ocl', LTLIAB: 'ltl', EQUITY: 'equity', INC: 'income', COGS: 'cogs', EXP: 'expense', EXINC: 'oi', EXEXP: 'oe' };
