        const v = { paper: m.querySelector('#pdf-paper').value, orientation: m.querySelector('#pdf-orient').value, fontSize: m.querySelector('#pdf-size').value, width: m.querySelector('#pdf-w').value, height: m.querySelector('#pdf-h').value };
