    const check = st.kind === 'bs' && st.balanced !== undefined ? `<p class="check-line ${st.balanced ? 'ok' : 'bad'}">${st.balanced ? '✓ Assets equal liabilities plus equity.' : '✗ Out of balance.'}</p>` : '';
