    e.preventDefault();
    const col = tile.parentNode, cols = [...cur.el.querySelectorAll('.snap-col')], ci = cols.indexOf(col), sibs = [...col.querySelectorAll(':scope > .tile')], i = sibs.indexOf(tile);
    if (k === 'ArrowUp' && i > 0) col.insertBefore(tile, sibs[i - 1]);
