      if (typeof it[1] === 'string') return `<a role="menuitem" href="${esc(it[1])}">${inner}</a>`;
      runs.push(it[1]); return `<button type="button" role="menuitem" data-run="${runs.length - 1}"${it[3] ? ` data-win="${esc(it[3])}"` : ''}>${inner}</button>`;
