    let a; try { a = I.ask(b, text, ctx); } catch (e) { a = { notUnderstood: true, text: 'That question could not be answered: ' + e.message, ctx: {}, actions: [] }; }
    const entry = { q: text, a }; st.log.push(entry); if (st.log.length > 30) st.log.shift();
