        <td><select data-cat="${k}|${i}" aria-label="What ${esc(l.label)} is" ${dis}>${l.category ? '' : '<option value="">Choose…</option>'}${CAT_OPTS.map(([v, t]) => `<option value="${v}"${l.category === v ? ' selected' : ''}>${esc(t)}</option>`).join('')}</select></td>
