    el.querySelectorAll('[data-amt]').forEach((x) => x.addEventListener('change', () => { const [k, i] = x.dataset.amt.split('|'), s = findStub(k); s.lines[+i].current = parseMoney(x.value); s.lines[+i].inferred = false; P.retotal(s); UI.render(); }));
